"""Acceptance checks for the docopt reimplementation. Run: PYTHONPATH=<dir> python3 checks.py"""
import sys
import io
import contextlib

from docopt import (
    docopt, DocoptExit, DocoptLanguageError, ParsedOptions,
    _Argument, _Command, _Option, _Either, _Required, _NotRequired,
    _OneOrMore, _OptionsShortcut, _parse_argv, _Tokens,
    _parse_docstring_sections, _parse_longer, _parse_options, _parse_pattern,
    _parse_shorts, _formal_usage, _lint_docstring, _transform,
    _Pattern, _LeafPattern, _BranchPattern, _DocSections, _SingleMatch,
    _parse_expr, _parse_seq, _parse_atom, _extras, _levenshtein,
    _levenshtein_norm, __version__,
)

results = []


def check(n, fn):
    try:
        fn()
    except Exception as e:
        results.append((n, False, f"{type(e).__name__}: {e}"))
    else:
        results.append((n, True, ""))


def c1():
    r = docopt('Usage: prog.py [-h] [--version] <input> [--output=<file>]\nOptions:\n  -h --help  Show help.\n  --version  Show version.\n  --output=<file>  Output file.', argv=['input.txt', '--output=out.txt'])
    assert r == {'<input>': 'input.txt', '--output': 'out.txt', '--help': False, '--version': False, '-h': False}, r


def c2():
    r = docopt('Usage: prog.py [--repeat=<n>] <file>...\nOptions:\n  --repeat=<n>  Repeat count [default: 1].', argv=['f1', 'f2', '--repeat=3'])
    assert r == {'<file>': ['f1', 'f2'], '--repeat': '3'}, r


def c3():
    r = docopt('Usage:\n  git add <file>...\n  git commit -m <msg>\n  git push [origin] [master]', argv=['commit', '-m', 'init'])
    assert r == {'add': False, 'commit': True, 'push': False, '<file>': None, '-m': True, '<msg>': 'init', 'origin': False, 'master': False}, r


def c4():
    r = docopt('Usage: prog.py [-a] [-b] [-c]', argv=['-abc'])
    assert r == {'-a': True, '-b': True, '-c': True}, r


def c5():
    buf = io.StringIO()
    try:
        with contextlib.redirect_stdout(buf):
            docopt('Usage: prog [--version]\nOptions: --version  Show version.', argv=['--version'], version='1.0.0')
    except SystemExit:
        pass
    else:
        raise AssertionError("no SystemExit")
    assert buf.getvalue().strip() == '1.0.0', repr(buf.getvalue())


def c6():
    try:
        docopt('Usage: prog.py <input>', argv=[])
    except DocoptExit as e:
        assert 'Usage: prog.py <input>' in str(e), str(e)
    else:
        raise AssertionError("no DocoptExit")


def c7():
    r = docopt('Usage: prog [--count=<n>]\nOptions: --count=<n>  Count [default: 5].', argv=[])
    assert r == {'--count': '5'}, r


def c8():
    r = docopt('Usage: prog (go | stop) [--speed=<s>]', argv=['go', '--speed=10'])
    assert r == {'go': True, 'stop': False, '--speed': '10'}, r


def c9():
    doc = 'Usage: prog [options]\nOptions: --version  Show version.\n         --verbose  Verbose mode.'
    try:
        docopt(doc, argv=['--ver'])
    except DocoptExit as e:
        assert '--version' in str(e) and '--verbose' in str(e), str(e)
    else:
        raise AssertionError("no DocoptExit for ambiguous")
    r = docopt('Usage: prog [options]\nOptions: --version\n         --verbose-more', argv=['--ver'])
    assert r == {'--version': True, '--verbose-more': False}, r


def c10():
    assert docopt('Usage: prog [-v -v]', argv=[]) == {'-v': 0}
    assert docopt('Usage: prog [-v -v]', argv=['-v']) == {'-v': 1}
    assert docopt('Usage: prog [-v -v]', argv=['-vv']) == {'-v': 2}
    assert docopt('Usage: prog NAME...', argv=['a', 'b']) == {'NAME': ['a', 'b']}


def c11():
    assert docopt('Usage: prog (-a|-b)', argv=['-a']) == {'-a': True, '-b': False}
    try:
        docopt('Usage: prog (-a|-b)', argv=['-a', '-b'])
    except DocoptExit:
        pass
    else:
        raise AssertionError("no DocoptExit")


def c12():
    assert docopt('Usage: prog [options]\nOptions: -p PATH [default: ./]', argv=[]) == {'-p': './'}
    assert docopt('Usage: prog [-o <o>]...\nOptions: -o <o> [default: x y]', argv=[]) == {'-o': ['x', 'y']}


def c13():
    args = docopt('Usage: prog [-vqrd] [FILE]\nOptions:\n  -d --dash-arg\n  -v\n  -q\n  -r\n', argv=['-v', '-d', 'file.py'])
    assert args.v is True and args.dash_arg is True, args


def c14():
    assert docopt('usage: prog [-o] [--] <arg>\noptions: -o', argv=['--', '-o']) == {'-o': False, '<arg>': '-o', '--': True}
    assert docopt('usage: prog [-o] [--] <arg>\noptions: -o', argv=['-o', '1']) == {'-o': True, '<arg>': '1', '--': False}


def c15():
    try:
        docopt('Usage: prog [a [b]')
    except DocoptLanguageError:
        pass
    else:
        raise AssertionError("no DocoptLanguageError")


def c16():
    assert docopt('usage: prog [<input file>]', argv=['f.txt']) == {'<input file>': 'f.txt'}
    assert docopt('usage: prog [--input=<file name>]...', argv=['--input', 'a.txt', '--input=b.txt']) == {'--input': ['a.txt', 'b.txt']}


def c17():
    assert docopt('usage: prog\n       prog <a> <b>', argv=['1', '2']) == {'<a>': '1', '<b>': '2'}
    assert docopt('usage: prog\n       prog <a> <b>', argv=[]) == {'<a>': None, '<b>': None}


def c18():
    assert docopt('uSaGe: prog [options]', argv=[]) == {}
    assert docopt("My Program's Usage: prog [options]", argv=[]) == {}


def c19():
    r = docopt('Usage: prog [options]\n--alpha\n-b, --bravo\n-c ARG, --charlie ARG  Something [default: foo]', argv=[])
    assert r == {'--alpha': False, '--bravo': False, '--charlie': 'foo', '-b': False, '-c': 'foo'}, r


def c20():
    assert docopt('usage: prog [-]', argv=['-']) == {'-': True}


def c21():
    doc = 'My prog.\n\nUsage:\n    myprog [options]\nOptions:\n    --foo\n    --bar\n'
    try:
        docopt(doc, argv=[])
    except DocoptLanguageError:
        pass
    else:
        raise AssertionError("no DocoptLanguageError")


def c22():
    assert _levenshtein('kitten', 'sitting') == 3
    assert _levenshtein_norm('', '') == 0.0


for i in range(1, 23):
    check(i, globals()[f"c{i}"])

for n, ok, msg in results:
    print(f"check {n}: {'PASS' if ok else 'FAIL'} {msg}")
sys.exit(0 if all(ok for _, ok, _ in results) else 1)

